```
// Input:
//   scene: a 3D scene represented as a mesh with vertices, triangles, and materials
//   camera: a camera position and orientation
//   light_source: a light source position and intensity
//   bg_color: the background color

// Output:
//   final_color: the final color of the rendered image

// Step 1: Pre-compute G (Geometry Term)
G[vertex] = 1 ( normalize the geometry term )

// Step 2: Pre-compute F (Fresnel Term)
F[vertex] = fresnel_term(material_refractive_index, material_refl_index, normal_vector)

// Step 3: Compute indirect illumination
for each light_source:
  // Compute the radiance at each vertex
  L[vertex] = light_source_intensity * G[vertex] * F[vertex] * max(0, dot(normal_vector, light_source_direction))

  // Compute the indirect irradiance
  I = 0
  for each neighboring vertex:
    weighting = 1 / (distance(vertex, neighboring_vertex)^2)
    I += weighting * L[neighboring_vertex]

  // Compute the indirect illumination
  indirect_illumination = I * F[vertex]

  // Add indirect illumination to the final color
  final_color += indirect_illumination

// Step 4: Refraction
for each material with refractive index != 1:
  // Compute the refraction term
  R[vertex] = refraction_term(material_refractive_index, normal_vector)

  // Add refraction term to the final color
  final_color += R[vertex]

// Step 5: Transmission
for each material with refractive index != 1:
  // Compute the transmission term
  T[vertex] = transmission_term(material_refractive_index, normal_vector)

  // Add transmission term to the final color
  final_color += T[vertex]

// Step 6: Shadows
for each light_source:
  // Compute the shadow mask
  shadow_mask = 1
  for each occluding surface:
    if distance(vertex, occluding_surface) < occluding_surface_radius:
      shadow_mask = 0

  // Apply shadow mask to indirect illumination
  indirect_illumination *= (1 - shadow_mask)

// Step 7: Final Color
final_color += bg_color
```
