  noStroke();
  fill(255, 0, 0); // red
}

function draw() {
  background(0); // black
  translate(width / 2, height / 2);
  rotateY(map(sin(frameCount * 0.01), -1, 1, -PI, PI));
  rotateX(map(sin(frameCount * 0.01), -1, 1, -PI, PI));
  heart();
}

function heart() {
