}

function fractalHeart(size) {
  push();
  translate(0, -size / 2, 0);
  box(size, size / 2, size / 2); // base of the heart
  pop();

  push();
  translate(0, size / 2, 0);
  rotateY(PI / 4);
  rotateX(PI / 4);
  fractalHeart(size / 2);
  pop();

  push();
  translate(0, -size / 2, 0);
  rotateY(-PI / 4);
  rotateX(-PI / 4);
  fractalHeart(size / 2);
  pop();
}

function mouseWheel(event) {
