```jsx
import React, { useState, useEffect } from 'react';

const AutoComplete = ({ options, placeholder }) => {
  const [value, setValue] = useState('');
  const [filteredOptions, setFilteredOptions] = useState(options);
  const [showOptions, setShowOptions] = useState(false);

  useEffect(() => {
    const filterOptions = () => {
      if (value.length > 0) {
        const filtered = options.filter((option) => {
          return Object.values(option).join('').toLowerCase().includes(value.toLowerCase());
        });
        setFilteredOptions(filtered);
      } else {
        setFilteredOptions(options);
      }
    };
    filterOptions();
  }, [value, options]);

  const handleInputChange = (e) => {
    setValue(e.target.value);
  };

  const handleOptionSelect = (option) => {
    setValue(option);
    setShowOptions(false);
  };

  const renderOptions = () => {
    let listItems = [];
    filteredOptions.forEach((option) => {
      listItems.push(<li onClick={() => handleOptionSelect(option)} key={option}>{option}</li>);
    });
    return (
      <ul>
        {listItems}
      </ul>
    );
  };

  return (
    <div>
      <input type="text" value={value} onChange={handleInputChange} placeholder={placeholder} />
      {showOptions && renderOptions()}
    </div>
  );
};

export default AutoComplete;
