```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

class HelloServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        listener.Start();

        Console.WriteLine("Server started. Press any key to stop...");
        Console.ReadKey();

        listener.Stop();
    }

    static void HandleRequest(HttpListenerContext context)
    {
        string response = "Hello";
        byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);

        context.Response.ContentType = "text/plain";
        context.Response.ContentLength64 = buffer.Length;
        context.Response.OutputStream.Write(buffer, 0, buffer.Length);
        context.Response.OutputStream.Close();
    }
}

class HttpListenerCallBack : IAsyncResult
{
    private HttpListener _listener;
    private AsyncCallback _callback;

    public HttpListenerCallBack(HttpListener listener, AsyncCallback callback)
    {
        _listener = listener;
        _callback = callback;
    }

    public IAsyncResult BeginInvoke(HttpListenerContext context, AsyncCallback callback)
    {
        _listener.BeginGetContext(new AsyncCallback(Callback), this);
        return this;
    }

    public void Callback(IAsyncResult result)
    {
        _callback(result);
    }
}
```
