// Функция для вычисления интеграла методом прямоугольников
double integralRectangle(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

// Функция для вычисления интеграла методом трапеций
double integralTrapezoid(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h) + f(a + (i + 1) * h);
    }
    sum /= 2;
    return h * sum;
}

// Функция для вычисления интеграла методом Симпсона
double integralSimpson(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i <= n; i++) {
        sum += 2 * f(a + i * h);
    }
    sum *= h / 3;
    return sum;
}

// Функция для вычисления интеграла в отдельном потоке
DWORD WINAPI integralThread(LPVOID param) {
    struct {
        double (*f)(double);
        double a;
        double b;
        int n;
        double *result;
        HANDLE mutex;
    } *data = (struct {} *)param;

    data->result[0] = 0;
    double (*f)(double) = data->f;

    //يمмелочные вычисления
    Sleep(100); // добавить задержку для иллюстрации многопоточности

    data->result[0] = integralRectangle(f, data->a, data->b, data->n);

    // выключить мьютекс
    ReleaseMutex(data->mutex);

    return 0;
}

int main() {
    const int n = 4; // количество потоков
    const int N = 10000; // количество разбиений

    double (*f)(double) = [](double x) { return x * x; }; // пример функции для интеграла

    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE sem = CreateSemaphore(NULL, 0, n, NULL);

    double results[n];

    for (int i = 0; i < n; i++) {
        struct {
            double (*f)(double);
            double a;
            double b;
            int n;
            double *result;
            HANDLE mutex;
        } data = {f, 0, 1, N, &results[i], mutex};
        CREATE_THREAD(NULL, 0, integralThread, &data, NULL);
    }

    // ожидаем завершения вычислений всеми потоками
    for (int i = 0; i < n; i++) {
        WaitForSingleObject(sem, INFINITE);
    }

    // вывод результатов
    for (int i = 0; i < n; i++) {
        std::cout << "Result " << i << ": " << results[i] << std::endl;
    }

    CloseHandle(mutex);
    CloseHandle(sem);

    return 0;
}
