```c
#include <iostream>

struct Node {
    int value;
    Node* left;
    Node* right;
};

int buscarRecursiva(Node* root, int target) {
    if (root == nullptr) {
        return -1; // valor no encontrado
    }

    if (root->value == target) {
        return root->value; // valor encontrado
    }

    int leftResult = buscarRecursiva(root->left, target);
    if (leftResult != -1) {
        return leftResult;
    }

    return buscarRecursiva(root->right, target);
}

