**Búsqueda Iterativa:**
```c
int buscarIterativa(Node* root, int target) {
    if (root == nullptr) {
        return -1; // valor no encontrado
    }

    while (root != nullptr) {
        if (root->value == target) {
            return root->value; // valor encontrado
        }

        if (target < root->value) {
            root = root->left;
        } else {
            root = root->right;
        }
    }

    return -1; // valor no encontrado
}
```
